    const fontOpts = Object.keys(FONTS).map(f => [f, f + (SERIFS.includes(f) ? ' (Serif)' : '')]);
    const presets = THEME_PRESETS.map((t, i) => `<button class="text-left rounded-[calc(var(--r)-4px)] border ${d.primary.toLowerCase() === t.primary.toLowerCase() ? 'border-p ring-4 ring-p/10' : 'border-line'} bg-card p-3 hover:border-p transition-colors" data-a="theme-preset" data-i="${i}"><div class="flex gap-1">${[t.night, t.primary, t.secondary, t.accent].map(c => `<span class="w-5 h-5 rounded-full border border-line2" style="background:${c}"></span>`).join('')}</div><div class="text-[13px] font-medium mt-2">${t.name}</div></button>`).join('');
    return sCard('eye', 'Erscheinungsbild', 'Dunkel oder hell – für die App und getrennt für das Kundendokument.', `<div class="grid sm:grid-cols-2 gap-6"><div><span class="lbl">Kundendokument</span>${seg('s:design.pdfTheme', [['light', 'Hell'], ['mixed', 'Gemischt'], ['dark', 'Dunkel']])}<div class="hint">Gemischt: dunkles Deckblatt und dunkle Highlights, Inhaltsseiten hell und gut druckbar.</div></div></div>`)
